    buildFactoryState: buildFactoryState,
    publishCommands: publishCommands,
    publishFactoryState: publishFactoryState,
    fetchPreviousState: fetchPreviousState,
    stampOf: stampOf,
    snapshotPutCommand: snapshotPutCommand,

