        (lanes[laneId] || []).forEach(function (c) {
            if (!c) return;
            if (c.pr != null) { ix.pr[c.pr] = c; ix.prLane[c.pr] = laneId; }
            if (c.issue != null) {
                ix.issue[c.issue] = c;
                if (!ix.issueState[c.issue]) ix.issueState[c.issue] = laneId;
            }
