                var spRunList = spRuns.workflow_runs || spRuns.workflowRuns || [];
                var spFull = spRepo.owner + '/' + spRepo.repo;
                // Schema 2 sources (owner 2026-10-01): recently merged PRs
                // (merged_recent lane — GitHub merged_at is exact), the
