        stamp + '.json' +
        ' -f branch=' + tagOf(cfg) +
        ' -f message=' + shellQuote('factory state snapshot ' + stamp +
            ' [skip ci]') +
        ' -f content="$(printf %s ' + shellQuote(json) + ' | base64)"';
