    var stamp = stampOf(state);
    exec({ command: snapshotPutCommand(state, cfg, stamp) });
    var indexPath = 'data/' + base + '-history.json';
    var snaps = [];
    var sha = '';
    try {
        sha = execOut(exec, 'gh api repos/' + repo + '/contents/' +
            indexPath + '?ref=' + branch + ' --jq .sha');
