function normTokenRow(r) {
    var prompt = +r.prompt || 0;
    var completion = +r.completion || 0;
    return {
        leg: r.leg == null ? null : String(r.leg),
        at: r.at == null ? null : String(r.at),
        prompt: prompt,
        completion: completion,
        total: +r.total || (prompt + completion)
